// The thumbnail of each new A3 request (reminders send none). The worker serves it against the
// metadata job's media token (D-062). Replace the base URL on import.
const WORKER = 'REPLACE_WITH_WORKER_URL';
const rows = $input.all().filter((item) => item.json.kind === 'REQUEST' && item.json.metadata);
return rows.map(({ json: row }) => {
  const meta = typeof row.metadata === 'string' ? JSON.parse(row.metadata) : row.metadata;
  const shortId = String(row.video_id).slice(0, 8);
  return {
    json: {
      url: `${WORKER}/media/${row.video_id}/${row.version}/${meta.job_id}/thumbnail.jpg?t=${meta.token}`,
      caption: `🏷 #${shortId} v${row.version} · thumbnail (shot ${meta.thumbnail_shot})`,
    },
  };
});

// A3 (D-062): one message per REQUEST/REMINDER row of final_due(), after its thumbnail (Vietnamese,
// D-061); the metadata is quoted as written, the description collapsed. Notes come back as a reply
// to this message (WF-06 finds the request by the hidden meta link). Callback data: a3:<A|G>:<token>.
// Shared Telegram formatting (same in every approval message node): the text goes out as HTML,
// times in Vietnam time (UTC+7, no daylight saving), and the request token rides in a hidden link
// at the start, so a reply to the message finds its request (WF-06) without showing the token.
const esc = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const vnTime = (value) => {
  const d = new Date(new Date(value).getTime() + 7 * 3_600_000);
  const p = (n) => String(n).padStart(2, '0');
  return `${p(d.getUTCHours())}:${p(d.getUTCMinutes())} ${p(d.getUTCDate())}/${p(d.getUTCMonth() + 1)}`;
};
const hiddenRef = (kind, token) => `<a href="https://t.me/?${kind}=${token}">\u200d</a>`;
const CHECKS = {
  format: 'định dạng',
  size: 'kích thước',
  duration: 'thời lượng',
  loudness: 'âm lượng',
  subtitles: 'phụ đề',
  'black frames': 'khung hình đen',
  silence: 'im lặng',
};
const DESCRIPTION_CHARS = 1500;
const rows = $input.all().filter((item) => ['REQUEST', 'REMINDER'].includes(item.json.kind) && typeof item.json.token === 'string');
const parse = (value) => (typeof value === 'string' ? JSON.parse(value) : value);
return rows.map(({ json: row }) => {
  const shortId = String(row.video_id).slice(0, 8);
  const reminder = row.kind === 'REMINDER';
  const meta = parse(row.metadata);
  const description = String(meta?.description ?? '').slice(0, DESCRIPTION_CHARS);
  const body = meta
    ? [
        ...(description ? [`<blockquote expandable>${esc(description)}</blockquote>`] : []),
        `Tag: ${esc((meta.tags ?? []).join(', '))}`,
        `QA 1080p ${esc(meta.qa_level ?? '?')}`,
        ...(meta.qa ?? [])
          .filter((check) => check.level !== 'PASS')
          .map((check) => `⚠️ ${esc(CHECKS[check.name] ?? check.name)}: ${esc(check.detail)}`),
      ]
    : [];
  const html = [
    `${hiddenRef('meta', row.token)}<b>${reminder ? '⏰ Nhắc: ' : ''}🏷 Duyệt metadata</b> · bước 5/5 · A3 lần ${row.round}`,
    `«${esc(meta?.title ?? row.title ?? '?')}»`,
    `#${shortId} v${row.version} · Duyệt → lưu lên Google Drive, hoàn tất`,
    ...(reminder ? [] : body),
    `⏰ Hạn ${vnTime(row.expires_at)} · ↩️ Reply để góp ý, hoặc bấm Viết lại`,
  ].join('\n');
  return { json: { html, approve: `a3:A:${row.token}`, regenerate: `a3:G:${row.token}` } };
});

// A verified archive (DONE rows of final_due(), D-062/D-063): where it is, what it cost, and whether
// to delete the Mac copy now. Only the owner's Xóa counts (cleanup_decide); the worker re-verifies
// the archive before deleting. Callback data: cl:<A|R>:<token>.
const rows = $input.all().filter((item) => item.json.kind === 'DONE' && typeof item.json.token === 'string');
const parse = (value) => (typeof value === 'string' ? JSON.parse(value) : value);
const gb = (bytes) => `${(Number(bytes ?? 0) / 1073741824).toFixed(2)} GB`;
const targets = { gdrive: 'Google Drive', nextcloud: 'Nextcloud' };
return rows.map(({ json: row }) => {
  const meta = parse(row.metadata) ?? {};
  const report = parse(row.report) ?? {};
  const cost = Object.entries(report.cost ?? {})
    .map(([currency, total]) => `${Math.round(total * 100) / 100} ${currency}`)
    .join(', ');
  const text = [
    '✅ Video hoàn tất',
    `«${meta.title ?? row.title ?? '?'}» · #${String(row.video_id).slice(0, 8)} v${row.version}`,
    `📦 ${targets[report.target] ?? report.target} (đã kiểm tra checksum): ${report.path}`,
    `${report.file_count} file · ${(Number(report.total_bytes ?? 0) / 1048576).toFixed(1)} MB · chi phí ${cost || 'chưa ghi nhận'} · agent ${report.agent_minutes ?? 0} phút`,
    `Hashtag: ${(meta.hashtags ?? []).join(' ')}`,
    '',
    `🗑 Xóa bản trên Mac (${gb(report.local_bytes)})? Chỉ chủ sở hữu bấm được; không trả lời trong 7 ngày thì giữ lại.`,
  ].join('\n');
  return { json: { text: text.slice(0, 4096), approve: `cl:A:${row.token}`, reject: `cl:R:${row.token}` } };
});

// The Mac copy was deleted after the owner's approval and a fresh check of the archive (D-063).
const rows = $input.all().filter((item) => item.json.kind === 'CLEANED');
const parse = (value) => (typeof value === 'string' ? JSON.parse(value) : value);
return rows.map(({ json: row }) => {
  const report = parse(row.report) ?? {};
  const text = [
    `🗑 Đã xóa bản trên Mac: ${(Number(report.freed_bytes ?? 0) / 1073741824).toFixed(2)} GB`,
    `«${row.title ?? '?'}» · #${String(row.video_id).slice(0, 8)} v${row.version}`,
    `Bản lưu (đã kiểm tra lại ngay trước khi xóa): ${report.remote_dir}`,
  ].join('\n');
  return { json: { text } };
});
